inline void ClientCounterReset( ClientCounter & value );
inline void SnapshotReset( Snapshot & value );

inline void HelloReset( Hello & value )
{
    value.proto = 0;
    value.min_peer = 0;
}

inline void SessionInfoReset( SessionInfo & value )
{
    value.friend_name.value = 0; // *string — null
    value.harness.value = 0; // *string — null
    value.account.value = 0; // *string — null
    value.model.value = 0; // *string — null
    value.effort.value = 0; // *string — null
    value.instance.value = 0; // *string — null
    value.title.value = 0; // *string — null
}

inline void EntryChangeReset( EntryChange & value )
{
    value.kind = EntryKind::None;
    value.closed = false;
    value.offset = 0;
    value.tail.value = 0; // *string — null
}

inline void SessionChangeQueueTextReset( SessionChangeQueueText & value )
{
    value.value.value = 0;
}

inline void SessionChangeReset( SessionChange & value )
{
    value.id = 0;
    value.changed = false;
    SessionInfoReset( value.info );
    value.activity = Activity::Idle;
    value.first = 0;
    value.keep_from = 0;
    value.entries.elements.value = 0; // EntryChange: empty
    value.entries.count = 0;
    value.entries.padding = 0;
    value.queue_changed = false;
    value.queue.elements.value = 0; // SessionChangeQueueText: empty
    value.queue.count = 0;
    value.queue.padding = 0;
}

inline void SessionsDiffReset( SessionsDiff & value )
{
    value.sessions.elements.value = 0; // SessionChange: empty
    value.sessions.count = 0;
    value.sessions.padding = 0;
}

inline void ActionReset( Action & value )
{
    value.kind = ActionKind::None;
    value.session = 0;
    value.friend_name.value = 0; // *string — null
    value.text.value = 0; // *string — null
    value.account.value = 0; // *string — null
}

inline void ActionsDiffReset( ActionsDiff & value )
{
    value.start = 0;
    value.actions.elements.value = 0; // Action: empty
    value.actions.count = 0;
    value.actions.padding = 0;
}

inline void StoreEntryReset( StoreEntry & value )
{
    value.kind = EntryKind::None;
    value.closed = false;
    value.text.value = 0; // *string — null
}

inline void DriverWaitingTextReset( DriverWaitingText & value )
{
    value.value.value = 0;
}

inline void DriverReset( Driver & value )
{
    value.next_turn = 0;
    value.open_turn = 0;
    value.session.value = 0; // *string — null
    value.waiting.elements.value = 0; // DriverWaitingText: empty
    value.waiting.count = 0;
    value.waiting.padding = 0;
    value.summary = false;
    value.session_dir.value = 0; // *string — null
}

inline void RecordReset( Record & value )
{
    value.session = 0;
    value.changes.elements.value = 0; // Change: empty
    value.changes.count = 0;
    value.changes.padding = 0;
    value.client.value = 0; // *string — null
    value.applied = 0;
}

inline void StoreSessionQueueTextReset( StoreSessionQueueText & value )
{
    value.value.value = 0;
}

inline void StoreSessionReset( StoreSession & value )
{
    value.id = 0;
    SessionInfoReset( value.info );
    value.transcript.elements.value = 0; // StoreEntry: empty
    value.transcript.count = 0;
    value.transcript.padding = 0;
    value.queue.elements.value = 0; // StoreSessionQueueText: empty
    value.queue.count = 0;
    value.queue.padding = 0;
    DriverReset( value.driver );
}

inline void ClientCounterReset( ClientCounter & value )
{
    value.client.value = 0; // *string — null
    value.applied = 0;
}

inline void SnapshotReset( Snapshot & value )
{
    value.next_session = 0;
    value.sessions.elements.value = 0; // StoreSession: empty
    value.sessions.count = 0;
    value.sessions.padding = 0;
    value.clients.elements.value = 0; // ClientCounter: empty
    value.clients.count = 0;
    value.clients.padding = 0;
}

// ---- the arena's reset hook (docs/SPEC-TABLES.md §6) ----
//
// TableWorker::Alloc is a template and cannot name a member's Reset, so
// the arena reaches it through this overload set by argument-dependent
// lookup. It is how a node born in raw arena storage comes to hold the
// declared defaults without value-initialising the whole aggregate.

inline void TableReset( Hello & value ) { HelloReset( value ); }
inline void TableReset( SessionInfo & value ) { SessionInfoReset( value ); }
inline void TableReset( EntryChange & value ) { EntryChangeReset( value ); }
inline void TableReset( SessionChangeQueueText & value ) { SessionChangeQueueTextReset( value ); }
inline void TableReset( SessionChange & value ) { SessionChangeReset( value ); }
inline void TableReset( SessionsDiff & value ) { SessionsDiffReset( value ); }
inline void TableReset( Action & value ) { ActionReset( value ); }
inline void TableReset( ActionsDiff & value ) { ActionsDiffReset( value ); }
inline void TableReset( StoreEntry & value ) { StoreEntryReset( value ); }
inline void TableReset( DriverWaitingText & value ) { DriverWaitingTextReset( value ); }
inline void TableReset( Driver & value ) { DriverReset( value ); }
inline void TableReset( Record & value ) { RecordReset( value ); }
inline void TableReset( StoreSessionQueueText & value ) { StoreSessionQueueTextReset( value ); }
inline void TableReset( StoreSession & value ) { StoreSessionReset( value ); }
inline void TableReset( ClientCounter & value ) { ClientCounterReset( value ); }
inline void TableReset( Snapshot & value ) { SnapshotReset( value ); }

