                        // cannot fire on it. A count above the int32 storage cap is the
                        // fill's refusal, and it moves no counter, the widening included.
                        TableListFill<EntryChange> fill = TableListFillBegin( nodes, value.entries, count );
                        if ( fill.refused )
                        {
                            nodes.refused = true;
                            return false;
                        }
