// SessionChangeExtentAt: the node extent SessionChange's lists and maps take, PRE-ORDER.
// The default native mode advances exactly as SessionChangeExtentPack (§2.8, §2.9).
template <typename Ctx, bool schema_cook_extent = false>
inline bool SessionChangeExtentAt( const Ctx & ctx, const SessionChange & value, int64_t & at )
{
    {
        TableListCursor<EntryChange> cursor = TableListElements( ctx, value.entries );
        if ( !cursor.ok ) { return false; }
        if constexpr ( schema_cook_extent )
        {
            at = ( at + 7 ) & ~(int64_t) 7;
            at += (int64_t) cursor.count * 24; // canonical cook layout
        }
        else
        {
            at = ( at + (int64_t) alignof( EntryChange ) - 1 ) & ~( (int64_t) alignof( EntryChange ) - 1 );
            at += (int64_t) cursor.count * (int64_t) sizeof( EntryChange ); // native pack layout
        }
    }
    {
        TableListCursor<SessionChangeQueueText> cursor = TableListElements( ctx, value.queue );
        if ( !cursor.ok ) { return false; }
        if constexpr ( schema_cook_extent )
        {
            at = ( at + 7 ) & ~(int64_t) 7;
            at += (int64_t) cursor.count * 8; // canonical cook layout
        }
        else
        {
            at = ( at + (int64_t) alignof( SessionChangeQueueText ) - 1 ) & ~( (int64_t) alignof( SessionChangeQueueText ) - 1 );
            at += (int64_t) cursor.count * (int64_t) sizeof( SessionChangeQueueText ); // native pack layout
        }
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, element by element in index order
        {
            if ( !SessionChangeQueueTextExtentAt<Ctx, schema_cook_extent>( ctx, cursor[i], at ) ) { return false; }
        }
    }
    return true;
}

