// SessionChangeExtentPack: carve SessionChange's arrays out of the node's extent and copy the
// entries in ASCENDING key order and the elements in INDEX order, PRE-ORDER,
// advancing the same running offset SessionChangeExtentAt advances (§2.8, §2.9).
template <typename Ctx>
inline bool SessionChangeExtentPack( const Ctx & ctx, const SessionChange & src, SessionChange & dst, uint8_t * extent, int64_t & at, int64_t capacity )
{
    {
        TableListCursor<EntryChange> cursor = TableListElements( ctx, src.entries );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( EntryChange ) - 1 ) & ~( (int64_t) alignof( EntryChange ) - 1 );
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( EntryChange );
        if ( at + bytes > capacity ) { return false; }
        EntryChange * placed = (EntryChange *) ( extent + at );
        at += bytes;
        dst.entries.count = cursor.count;
        dst.entries.padding = 0;
        dst.entries.elements.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.entries.elements ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            memcpy( (void *) ( placed + i ), (const void *) &cursor[i], sizeof( EntryChange ) ); // trivially copyable, by construction
        }
    }
    {
        TableListCursor<SessionChangeQueueText> cursor = TableListElements( ctx, src.queue );
        if ( !cursor.ok ) { return false; }
        at = ( at + (int64_t) alignof( SessionChangeQueueText ) - 1 ) & ~( (int64_t) alignof( SessionChangeQueueText ) - 1 );
        const int64_t bytes = (int64_t) cursor.count * (int64_t) sizeof( SessionChangeQueueText );
        if ( at + bytes > capacity ) { return false; }
        SessionChangeQueueText * placed = (SessionChangeQueueText *) ( extent + at );
        at += bytes;
        dst.queue.count = cursor.count;
        dst.queue.padding = 0;
        dst.queue.elements.value = cursor.count > 0 ? (int64_t) ( (uint8_t *) placed - (const uint8_t *) &dst.queue.elements ) : 0;
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            memcpy( (void *) ( placed + i ), (const void *) &cursor[i], sizeof( SessionChangeQueueText ) ); // trivially copyable, by construction
        }
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            if ( !SessionChangeQueueTextExtentPack( ctx, cursor[i], placed[i], extent, at, capacity ) ) { return false; }
        }
    }
    return true;
}

