// SnapshotWireExtent: the extent Snapshot's lists and maps command, from the FRAMING alone.
// It reads no field value, so a caller can refuse a number it did not
// expect before one byte is allocated (docs/SPEC-TABLES.md §6.5).
inline bool SnapshotWireExtent( const uint8_t * body, int64_t length, int64_t & at, const TableIdTable * ids, TableRefuseReason & reason )
{
    TableReport scratch; // the scan's framing damage is the LOAD's to report
    TableReader r( body, length, &scratch, ids );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) ) { return true; }
        if ( field_ref == 0 ) { return true; }
        if ( ids == NULL || field_ref > (uint64_t) ids->count ) { return true; }
        const uint64_t field_id = ids->at( field_ref );
        if ( !r.has( 1 ) ) { return true; }
        uint8_t field_kind = r.get8();
        if ( field_id == 0xacebadbd2040ebacull && field_kind == 14 ) // sessions: an unbounded array
        {
            uint64_t list_len = 0;
            if ( !r.getleb( list_len ) || !r.room( list_len ) ) { return true; }
            const uint8_t * list_body = r.buffer + r.offset;
            r.offset += (int64_t) list_len;
            if ( !TableListWireExtent( list_body, (int64_t) list_len, at, (int64_t) sizeof( StoreSession ), (int64_t) alignof( StoreSession ), 13, 2, &StoreSessionWireExtent, ids, reason ) ) { return false; }
            continue;
        }
        if ( field_id == 0x6a29dc2880500ef7ull && field_kind == 14 ) // clients: an unbounded array
        {
            uint64_t list_len = 0;
            if ( !r.getleb( list_len ) || !r.room( list_len ) ) { return true; }
            const uint8_t * list_body = r.buffer + r.offset;
            r.offset += (int64_t) list_len;
            if ( !TableListWireExtent( list_body, (int64_t) list_len, at, (int64_t) sizeof( ClientCounter ), (int64_t) alignof( ClientCounter ), 13, 2, NULL, ids, reason ) ) { return false; }
            continue;
        }
        if ( !r.skip( field_kind ) ) { return true; }
    }
}

