// ChangeWireArmExtent: the extent one Change value's set arm commands, from the FRAMING alone (§2.6, §6.5).
inline bool ChangeWireArmExtent( TableReader & r, int64_t & at, TableRefuseReason & reason )
{
    uint64_t arm_ref = 0;
    if ( !r.getleb( arm_ref ) )
    {
        r.offset = r.size;
        return true;
    }
    if ( arm_ref == 0 ) { return true; } // None: the reference is the whole payload
    if ( r.ids == NULL || arm_ref > (uint64_t) r.ids->count )
    {
        r.offset = r.size;
        return true;
    }
    const uint64_t arm_id = r.ids->at( arm_ref );
    if ( !r.has( 1 ) )
    {
        r.offset = r.size;
        return true;
    }
    r.offset += 1; // the arm's kind byte
    uint64_t arm_len = 0;
    if ( !r.getleb( arm_len ) || !r.room( arm_len ) )
    {
        r.offset = r.size;
        return true;
    }
    const uint8_t * arm_body = r.buffer + r.offset;
    r.offset += (int64_t) arm_len;
    switch ( arm_id )
    {
        case 0xd0aef91bc49cc38aull: if ( !DriverWireExtent( arm_body, (int64_t) arm_len, at, r.ids, reason ) ) { return false; } break; // set_driver
        default: break; // an arm this reader cannot name reads None
    }
    return true;
}

// ChangeWireArmsExtent: that walk over an ARRAY of Change values, one arm header per element in its place (§2.6, §3).
inline bool ChangeWireArmsExtent( const uint8_t * body, int64_t length, int64_t & at, const TableIdTable * ids, TableRefuseReason & reason )
{
    TableReport scratch;
    TableReader r( body, length, &scratch, ids );
    if ( length < 2 ) { return true; }
    if ( r.get8() != 15 ) { return true; } // another element kind: the field reads empty
    uint64_t n = 0;
    if ( !r.getleb( n ) ) { return true; }
    for ( uint64_t i = 0; i < n && r.offset < r.size; i++ )
    {
        if ( !ChangeWireArmExtent( r, at, reason ) ) { return false; }
    }
    return true;
}

