// SessionChangeNumber: number everything SessionChange POINTS AT, in first-visit order —
// the fields in declaration order, a by-value edge descended in place.
// A reference to an entry whose descent is still OPEN is a data cycle,
// named here rather than recursed away (docs/SPEC-TABLES.md §3.1).
template <typename Ctx>
inline bool SessionChangeNumber( const Ctx & ctx, TableNumbering & numbering, const SessionChange & value )
{
    { // info (nested by value)
        if ( !SessionInfoNumber( ctx, numbering, value.info ) ) { return false; }
    }
    { // entries: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<EntryChange> cursor_entries = TableListElements( ctx, value.entries );
        if ( !cursor_entries.ok ) { return false; }
        for ( int32_t i = 0; i < cursor_entries.count; i++ )
        {
            if ( !EntryChangeNumber( ctx, numbering, cursor_entries[i] ) ) { return false; }
        }
    }
    { // queue: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<SessionChangeQueueText> cursor_queue = TableListElements( ctx, value.queue );
        if ( !cursor_queue.ok ) { return false; }
        for ( int32_t i = 0; i < cursor_queue.count; i++ )
        {
            if ( !SessionChangeQueueTextNumber( ctx, numbering, cursor_queue[i] ) ) { return false; }
        }
    }
    return true;
}

// SessionChangeCycleSlots: the cycle check's edges below one SessionChange, guards ignored.
template <typename Ctx>
inline bool SessionChangeCycleSlots( const Ctx & ctx, TableCycle & cycle, const SessionChange & value )
{
    (void) ctx;
    (void) cycle;
    (void) value;
    { // info (nested by value)
        if ( !SessionInfoCycleSlots( ctx, cycle, value.info ) ) { return false; }
    }
    { // entries: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<EntryChange> cursor_entries = TableListElements( ctx, value.entries );
        if ( !cursor_entries.ok ) { return false; }
        for ( int32_t i = 0; i < cursor_entries.count; i++ )
        {
            if ( !EntryChangeCycleSlots( ctx, cycle, cursor_entries[i] ) ) { return false; }
        }
    }
    { // queue: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<SessionChangeQueueText> cursor_queue = TableListElements( ctx, value.queue );
        if ( !cursor_queue.ok ) { return false; }
        for ( int32_t i = 0; i < cursor_queue.count; i++ )
        {
            if ( !SessionChangeQueueTextCycleSlots( ctx, cycle, cursor_queue[i] ) ) { return false; }
        }
    }
    return true;
}

// SessionChangePackMeasure: the packed region bytes of everything SessionChange POINTS AT.
// ONE VISIT PER NODE: `seen` carries the first-visit numbering (§3.1), so a
// node two references name is measured ONCE and packed once, and a
// reference to a node whose descent is still open is a data cycle, refused.
template <typename Ctx>
inline int64_t SessionChangePackMeasure( const Ctx & ctx, TablePackMap & seen, const SessionChange & value )
{
    int64_t bytes = 0;
    { // info (nested by value)
        int64_t inner = SessionInfoPackMeasure( ctx, seen, value.info );
        if ( inner < 0 ) { return -1; }
        bytes += inner;
    }
    { // entries: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<EntryChange> cursor_entries = TableListElements( ctx, value.entries );
        if ( !cursor_entries.ok ) { return -1; }
        for ( int32_t i = 0; i < cursor_entries.count; i++ )
        {
            int64_t inner = EntryChangePackMeasure( ctx, seen, cursor_entries[i] );
            if ( inner < 0 ) { return -1; }
            bytes += inner;
        }
    }
    { // queue: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<SessionChangeQueueText> cursor_queue = TableListElements( ctx, value.queue );
        if ( !cursor_queue.ok ) { return -1; }
        for ( int32_t i = 0; i < cursor_queue.count; i++ )
        {
            int64_t inner = SessionChangeQueueTextPackMeasure( ctx, seen, cursor_queue[i] );
            if ( inner < 0 ) { return -1; }
            bytes += inner;
        }
    }
    return bytes;
}

// SessionChangePack: copy src into dst (already placed), then lay every pointee out
// depth-first behind it, in FIELD ORDER, by bump allocation.
//
// ONE NODE, ONE BODY (§6.2): `seen` holds every node already placed and
// where it landed, so a node's FIRST reference lays it out and every later
// reference points BACK at that one body. A region delta therefore has no
// required sign (§6.3), and sharing and a back-reference are one fact. A
// reference to a node whose descent is still OPEN is a cycle, and this
// refuses it rather than packing one.
template <typename Ctx>
inline bool SessionChangePackEdges( const Ctx & ctx, TablePackMap & seen, const SessionChange & src, SessionChange & dst, uint8_t * base, int64_t capacity, int64_t & used );

template <typename Ctx>
inline bool SessionChangePack( const Ctx & ctx, TablePackMap & seen, const SessionChange & src, SessionChange & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    memcpy( (void *) &dst, (const void *) &src, sizeof( SessionChange ) ); // trivially copyable, by construction
    int64_t at = 0;
    uint8_t * extent = (uint8_t *) &dst + TableAlignUp64( (int64_t) sizeof( SessionChange ) );
    const int64_t room = capacity - ( (int64_t) ( extent - base ) );
    if ( !SessionChangeExtentPack( ctx, src, dst, extent, at, room ) ) { return false; }
    return SessionChangePackEdges( ctx, seen, src, dst, base, capacity, used );
}

template <typename Ctx>
inline bool SessionChangePackEdges( const Ctx & ctx, TablePackMap & seen, const SessionChange & src, SessionChange & dst, uint8_t * base, int64_t capacity, int64_t & used )
{
    { // info (nested by value)
        if ( !SessionInfoPackEdges( ctx, seen, src.info, dst.info, base, capacity, used ) ) { return false; }
    }
    { // entries: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<EntryChange> cursor_entries = TableListElements( ctx, src.entries );
        if ( !cursor_entries.ok ) { return false; }
        EntryChange * placed_entries = (EntryChange *) ( dst.entries.elements.value != 0 ? ( (uint8_t *) &dst.entries.elements + dst.entries.elements.value ) : NULL );
        for ( int32_t i = 0; i < cursor_entries.count; i++ )
        {
            if ( !EntryChangePackEdges( ctx, seen, cursor_entries[i], placed_entries[i], base, capacity, used ) ) { return false; }
        }
    }
    { // queue: a by-value edge, elements in INDEX order (§2.9, §3.1)
        TableListCursor<SessionChangeQueueText> cursor_queue = TableListElements( ctx, src.queue );
        if ( !cursor_queue.ok ) { return false; }
        SessionChangeQueueText * placed_queue = (SessionChangeQueueText *) ( dst.queue.elements.value != 0 ? ( (uint8_t *) &dst.queue.elements + dst.queue.elements.value ) : NULL );
        for ( int32_t i = 0; i < cursor_queue.count; i++ )
        {
            if ( !SessionChangeQueueTextPackEdges( ctx, seen, cursor_queue[i], placed_queue[i], base, capacity, used ) ) { return false; }
        }
    }
    return true;
}

