template <typename Ctx>
inline bool DriverWaitingTextNumber( const Ctx & ctx, TableNumbering & numbering, const DriverWaitingText & value )
{
    (void) ctx;
    (void) numbering;
    (void) value; // no pointers below this node
    return true;
}

// DriverWaitingTextCycleSlots: the cycle check's edges below one DriverWaitingText, guards ignored.
template <typename Ctx>
inline bool DriverWaitingTextCycleSlots( const Ctx & ctx, TableCycle & cycle, const DriverWaitingText & value )
{
    (void) ctx;
    (void) cycle;
    (void) value;
    return true;
}

