template <typename Ctx>
inline int64_t SessionsDiffMeasureBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableRetainIds & ids, const SessionsDiff & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    int64_t bytes = 1; // the ZERO REFERENCE that ends the body
    {
        // sessions: a kind 14 array of kind 13 elements, INDEX order (§2.9)
        TableListCursor<SessionChange> cursor_sessions = TableListElements( ctx, value.sessions );
        if ( !cursor_sessions.ok ) { return -1; } // the slot and the head disagree
        if ( cursor_sessions.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_sessions = ids.ref_at( 56, 0xacebadbd2040ebacull );
            int64_t body_sessions = 0;
            body_sessions += 1 + TableLebBytes( (uint64_t) ( cursor_sessions.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                const int64_t elem_bytes_sessions = SessionChangeMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 0, (uint32_t) ( elem_i_sessions ) ) );
                if ( elem_bytes_sessions < 0 ) { return -1; }
                body_sessions += TableLebBytes( (uint64_t) ( elem_bytes_sessions ) ) + ( elem_bytes_sessions );
            }
            bytes += TableLebBytes( ref_sessions ) + 1 + TableLebBytes( (uint64_t) ( body_sessions ) ) + ( body_sessions );
        }
    }
    bytes += TableRetainTailMeasure( retain, ids, path );
    return bytes;
}

template <typename Ctx>
inline bool SessionsDiffSaveBodyFieldsRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const SessionsDiff & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    {
        TableListCursor<SessionChange> cursor_sessions = TableListElements( ctx, value.sessions ); // sessions
        if ( !cursor_sessions.ok ) { return false; }
        if ( cursor_sessions.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_sessions = ids.ref_at( 56, 0xacebadbd2040ebacull );
            int64_t body_sessions = 0;
            body_sessions += 1 + TableLebBytes( (uint64_t) ( cursor_sessions.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                const int64_t elem_bytes_sessions = SessionChangeMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 0, (uint32_t) ( elem_i_sessions ) ) );
                if ( elem_bytes_sessions < 0 ) { return false; }
                body_sessions += TableLebBytes( (uint64_t) ( elem_bytes_sessions ) ) + ( elem_bytes_sessions );
            }
            w.header( ref_sessions, 14 );
            w.putleb( (uint64_t) body_sessions ); // sessions
            w.put8( 13 );
            w.putleb( (uint64_t) ( cursor_sessions.count ) );
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                {
                    const int64_t elem_len_sessions = SessionChangeMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 0, (uint32_t) ( elem_i_sessions ) ) );
                    if ( elem_len_sessions < 0 ) return false;
                    w.putleb( (uint64_t) elem_len_sessions );
                    if ( !SessionChangeSaveBodyRetain( ctx, numbering, w, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 0, (uint32_t) ( elem_i_sessions ) ) ) ) return false;
                }
            }
        }
    }
    if ( !TableRetainTailSave( retain, ids, w, path ) ) { return false; }
    return !w.overflow;
}

template <typename Ctx>
inline bool SessionsDiffSaveBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const SessionsDiff & value, TableRetain * retain, const TableRetainPath & path )
{
    if ( !SessionsDiffSaveBodyFieldsRetain( ctx, numbering, w, ids, value, retain, path ) ) { return false; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the body
    return !w.overflow;
}

