inline bool StoreSessionQueueTextLoadBodyRetain( TableReader & r, const TableNodeMap & nodes, StoreSessionQueueText & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) nodes;
    if ( nodes.refused ) { return false; }
    StoreSessionQueueTextReset( value ); // prefill declared defaults in place, then overlay
    // A RETAINED RECORD DIES WITH THE BODY OCCURRENCE THAT CARRIED IT
    // (docs/SPEC-TABLES.md §6.6): this body is being established, so
    // whatever an earlier occurrence of it left is discarded before the
    // winning one is read. The discard moves neither counter.
    TableRetainDiscardBody( retain, path );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) )
        {
            r.report->damaged = true;
            return false;
        }
        if ( field_ref == 0 )
        {
            return true;
        }
        if ( r.ids == NULL || field_ref > (uint64_t) r.ids->count )
        {
            r.report->damaged = true;
            return false;
        } // a reference ABOVE the entry count
        const uint64_t field_id = r.ids->at( field_ref );
        if ( !r.has( 1 ) )
        {
            r.report->damaged = true;
            return false;
        }
        uint8_t kind = r.get8();
        if ( ( field_id == kTableNodeTableFieldId && r.nested ) || field_id == kTableBuildVersionFieldId || field_id == kTableMessageVocabularyFieldId )
        {
            // A RESERVED ID IN ANY BODY BUT THE ONE WHOSE TRANSPORT IT IS,
            // IS MALFORMED (docs/SPEC-TABLES.md §3.1, §3.3). The node
            // table's is the ROOT body's alone, on the numbering's own
            // rule — a second numbering cannot exist — and the BUILD
            // VERSION's rides in the announcement and nowhere else. That
            // is damage, and damage discards the whole load (§4).
            r.report->damaged = true;
            return false;
        }
        switch ( field_id )
        {
            case 0x7ce4fd9430e80ceaull: // value
            {
                if ( kind != 12 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                uint64_t len = 0;
                if ( !r.getleb( len ) || !r.room( len ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                if ( !TableUtf8Valid( r.buffer + r.offset, len ) )
                {
                    r.report->damaged = true;
                    value.value.value = 0;
                    r.offset += (int64_t) len;
                    break;
                }
                if ( !schema_table_text_place_( nodes, value.value, r.buffer + r.offset, (int64_t) len ) )
                {
                    if ( !nodes.refused ) { r.report->damaged = true; }
                    return false;
                }
                r.offset += (int64_t) len;
                break;
            }
            case 0xffffffffffffffffull:
            {
                if ( !r.skip( kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !TableRetainCapture( retain, r, path, field_id, kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
        }
    }
}

template <typename Ctx>
inline int64_t StoreSessionMeasureBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableRetainIds & ids, const StoreSession & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    int64_t bytes = 1; // the ZERO REFERENCE that ends the body
    if ( value.id != 0 ) { bytes += TableLebBytes( ids.ref_at( 4, 0x08b72e07b55c3ac0ull ) ) + 1 + 8; } // id
    {
        const int32_t mark_info = ids.count;
        const uint64_t ref_info = ids.ref_at( 80, 0xf5d6a8c57ab94f05ull );
        const int64_t body_info = SessionInfoMeasureBodyRetain( ctx, numbering, ids, value.info, retain, TableRetainStepInto( path, 1, (uint32_t) ( 0 ) ) );
        if ( body_info < 0 ) { return -1; }
        if ( body_info > 1 ) { bytes += TableLebBytes( ref_info ) + 1 + TableLebBytes( (uint64_t) ( body_info ) ) + ( body_info ); } // info
        else { ids.truncate( mark_info ); } // an all-default nested table elides, and costs no entry
    }
    {
        // transcript: a kind 14 array of kind 13 elements, INDEX order (§2.9)
        TableListCursor<StoreEntry> cursor_transcript = TableListElements( ctx, value.transcript );
        if ( !cursor_transcript.ok ) { return -1; } // the slot and the head disagree
        if ( cursor_transcript.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_transcript = ids.ref_at( 75, 0xe4285b4aabc7d56bull );
            int64_t body_transcript = 0;
            body_transcript += 1 + TableLebBytes( (uint64_t) ( cursor_transcript.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_transcript = 0; elem_i_transcript < cursor_transcript.count; elem_i_transcript++ )
            {
                const int64_t elem_bytes_transcript = StoreEntryMeasureBodyRetain( ctx, numbering, ids, cursor_transcript[elem_i_transcript], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_transcript ) ) );
                if ( elem_bytes_transcript < 0 ) { return -1; }
                body_transcript += TableLebBytes( (uint64_t) ( elem_bytes_transcript ) ) + ( elem_bytes_transcript );
            }
            bytes += TableLebBytes( ref_transcript ) + 1 + TableLebBytes( (uint64_t) ( body_transcript ) ) + ( body_transcript );
        }
    }
    {
        // queue: a kind 14 array of kind 12 elements, INDEX order (§2.9)
        TableListCursor<StoreSessionQueueText> cursor_queue = TableListElements( ctx, value.queue );
        if ( !cursor_queue.ok ) { return -1; } // the slot and the head disagree
        if ( cursor_queue.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_queue = ids.ref_at( 59, 0xb11e8b146c5a21d8ull );
            int64_t body_queue = 0;
            body_queue += 1 + TableLebBytes( (uint64_t) ( cursor_queue.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_queue = 0; elem_i_queue < cursor_queue.count; elem_i_queue++ )
            {
                int32_t elem_len_queue = 0;
                const char * elem_text_queue = schema_table_text_at_( ctx, ( cursor_queue[elem_i_queue] ).value, elem_len_queue );
                if ( elem_text_queue == NULL ) { return -1; }
                body_queue += TableLebBytes( (uint64_t) ( elem_len_queue ) ) + ( elem_len_queue );
            }
            bytes += TableLebBytes( ref_queue ) + 1 + TableLebBytes( (uint64_t) ( body_queue ) ) + ( body_queue );
        }
    }
    {
        const int32_t mark_driver = ids.count;
        const uint64_t ref_driver = ids.ref_at( 64, 0xc85b78e3dea334ffull );
        const int64_t body_driver = DriverMeasureBodyRetain( ctx, numbering, ids, value.driver, retain, TableRetainStepInto( path, 4, (uint32_t) ( 0 ) ) );
        if ( body_driver < 0 ) { return -1; }
        if ( body_driver > 1 ) { bytes += TableLebBytes( ref_driver ) + 1 + TableLebBytes( (uint64_t) ( body_driver ) ) + ( body_driver ); } // driver
        else { ids.truncate( mark_driver ); } // an all-default nested table elides, and costs no entry
    }
    bytes += TableRetainTailMeasure( retain, ids, path );
    return bytes;
}

template <typename Ctx>
inline bool StoreSessionSaveBodyFieldsRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const StoreSession & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    if ( value.id != 0 )
    {
        w.header( ids.ref_at( 4, 0x08b72e07b55c3ac0ull ), 9 ); // id
        w.put64( uint64_t( value.id ) );
    }
    {
        const int32_t mark_info = ids.count;
        const uint64_t ref_info = ids.ref_at( 80, 0xf5d6a8c57ab94f05ull );
        const int64_t body_info = SessionInfoMeasureBodyRetain( ctx, numbering, ids, value.info, retain, TableRetainStepInto( path, 1, (uint32_t) ( 0 ) ) );
        if ( body_info < 0 ) return false; // storage invariant, refused as measure refuses it
        if ( body_info > 1 ) // all-default nested elides
        {
            w.header( ref_info, 13 );
            w.putleb( (uint64_t) body_info ); // info
            if ( !SessionInfoSaveBodyRetain( ctx, numbering, w, ids, value.info, retain, TableRetainStepInto( path, 1, (uint32_t) ( 0 ) ) ) ) return false;
        }
        else { ids.truncate( mark_info ); }
    }
    {
        TableListCursor<StoreEntry> cursor_transcript = TableListElements( ctx, value.transcript ); // transcript
        if ( !cursor_transcript.ok ) { return false; }
        if ( cursor_transcript.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_transcript = ids.ref_at( 75, 0xe4285b4aabc7d56bull );
            int64_t body_transcript = 0;
            body_transcript += 1 + TableLebBytes( (uint64_t) ( cursor_transcript.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_transcript = 0; elem_i_transcript < cursor_transcript.count; elem_i_transcript++ )
            {
                const int64_t elem_bytes_transcript = StoreEntryMeasureBodyRetain( ctx, numbering, ids, cursor_transcript[elem_i_transcript], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_transcript ) ) );
                if ( elem_bytes_transcript < 0 ) { return false; }
                body_transcript += TableLebBytes( (uint64_t) ( elem_bytes_transcript ) ) + ( elem_bytes_transcript );
            }
            w.header( ref_transcript, 14 );
            w.putleb( (uint64_t) body_transcript ); // transcript
            w.put8( 13 );
            w.putleb( (uint64_t) ( cursor_transcript.count ) );
            for ( int32_t elem_i_transcript = 0; elem_i_transcript < cursor_transcript.count; elem_i_transcript++ )
            {
                {
                    const int64_t elem_len_transcript = StoreEntryMeasureBodyRetain( ctx, numbering, ids, cursor_transcript[elem_i_transcript], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_transcript ) ) );
                    if ( elem_len_transcript < 0 ) return false;
                    w.putleb( (uint64_t) elem_len_transcript );
                    if ( !StoreEntrySaveBodyRetain( ctx, numbering, w, ids, cursor_transcript[elem_i_transcript], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_transcript ) ) ) ) return false;
                }
            }
        }
    }
    {
        TableListCursor<StoreSessionQueueText> cursor_queue = TableListElements( ctx, value.queue ); // queue
        if ( !cursor_queue.ok ) { return false; }
        if ( cursor_queue.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_queue = ids.ref_at( 59, 0xb11e8b146c5a21d8ull );
            int64_t body_queue = 0;
            body_queue += 1 + TableLebBytes( (uint64_t) ( cursor_queue.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_queue = 0; elem_i_queue < cursor_queue.count; elem_i_queue++ )
            {
                int32_t elem_len_queue = 0;
                const char * elem_text_queue = schema_table_text_at_( ctx, ( cursor_queue[elem_i_queue] ).value, elem_len_queue );
                if ( elem_text_queue == NULL ) { return false; }
                body_queue += TableLebBytes( (uint64_t) ( elem_len_queue ) ) + ( elem_len_queue );
            }
            w.header( ref_queue, 14 );
            w.putleb( (uint64_t) body_queue ); // queue
            w.put8( 12 );
            w.putleb( (uint64_t) ( cursor_queue.count ) );
            for ( int32_t elem_i_queue = 0; elem_i_queue < cursor_queue.count; elem_i_queue++ )
            {
                {
                    int32_t elem_len_queue = 0;
                    const char * elem_text_queue = schema_table_text_at_( ctx, ( cursor_queue[elem_i_queue] ).value, elem_len_queue );
                    if ( elem_text_queue == NULL ) { return false; }
                    w.putleb( (uint64_t) elem_len_queue );
                    w.raw( elem_text_queue, elem_len_queue );
                }
            }
        }
    }
    {
        const int32_t mark_driver = ids.count;
        const uint64_t ref_driver = ids.ref_at( 64, 0xc85b78e3dea334ffull );
        const int64_t body_driver = DriverMeasureBodyRetain( ctx, numbering, ids, value.driver, retain, TableRetainStepInto( path, 4, (uint32_t) ( 0 ) ) );
        if ( body_driver < 0 ) return false; // storage invariant, refused as measure refuses it
        if ( body_driver > 1 ) // all-default nested elides
        {
            w.header( ref_driver, 13 );
            w.putleb( (uint64_t) body_driver ); // driver
            if ( !DriverSaveBodyRetain( ctx, numbering, w, ids, value.driver, retain, TableRetainStepInto( path, 4, (uint32_t) ( 0 ) ) ) ) return false;
        }
        else { ids.truncate( mark_driver ); }
    }
    if ( !TableRetainTailSave( retain, ids, w, path ) ) { return false; }
    return !w.overflow;
}

template <typename Ctx>
inline bool StoreSessionSaveBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const StoreSession & value, TableRetain * retain, const TableRetainPath & path )
{
    if ( !StoreSessionSaveBodyFieldsRetain( ctx, numbering, w, ids, value, retain, path ) ) { return false; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the body
    return !w.overflow;
}

inline bool StoreSessionLoadBodyRetain( TableReader & r, const TableNodeMap & nodes, StoreSession & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) nodes;
    if ( nodes.refused ) { return false; }
    StoreSessionReset( value ); // prefill declared defaults in place, then overlay
    // A RETAINED RECORD DIES WITH THE BODY OCCURRENCE THAT CARRIED IT
    // (docs/SPEC-TABLES.md §6.6): this body is being established, so
    // whatever an earlier occurrence of it left is discarded before the
    // winning one is read. The discard moves neither counter.
    TableRetainDiscardBody( retain, path );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) )
        {
            r.report->damaged = true;
            return false;
        }
        if ( field_ref == 0 )
        {
            return true;
        }
        if ( r.ids == NULL || field_ref > (uint64_t) r.ids->count )
        {
            r.report->damaged = true;
            return false;
        } // a reference ABOVE the entry count
        const uint64_t field_id = r.ids->at( field_ref );
        if ( !r.has( 1 ) )
        {
            r.report->damaged = true;
            return false;
        }
        uint8_t kind = r.get8();
        if ( ( field_id == kTableNodeTableFieldId && r.nested ) || field_id == kTableBuildVersionFieldId || field_id == kTableMessageVocabularyFieldId )
        {
            // A RESERVED ID IN ANY BODY BUT THE ONE WHOSE TRANSPORT IT IS,
            // IS MALFORMED (docs/SPEC-TABLES.md §3.1, §3.3). The node
            // table's is the ROOT body's alone, on the numbering's own
            // rule — a second numbering cannot exist — and the BUILD
            // VERSION's rides in the announcement and nowhere else. That
            // is damage, and damage discards the whole load (§4).
            r.report->damaged = true;
            return false;
        }
        switch ( field_id )
        {
            case 0x08b72e07b55c3ac0ull: // id
            {
                if ( kind != 9 )
                {
                    if ( TableKindWidens( kind, 9 ) )
                    {
                        // WIDENED (§4): a kind that grew since the writer decodes
                        // exactly at its own width, the value lands, one widened counts
                        uint64_t widened_v = 0;
                        if ( !TableReadUnsignedAt( r, kind, widened_v ) )
                        {
                            r.report->damaged = true;
                            return false;
                        }
                        uint64_t decoded_v = (uint64_t) widened_v;
                        value.id = decoded_v;
                        r.report->widened++;
                        break;
                    }
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                if ( !r.has( 8 ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                uint64_t decoded_v = uint64_t( r.get64() );
                value.id = decoded_v;
                break;
            }
            case 0xf5d6a8c57ab94f05ull: // info
            {
                if ( kind != 13 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                TableRetainDiscardField( retain, path, 1 );
                uint64_t body_len = 0;
                if ( !r.getleb( body_len ) || !r.room( body_len ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                {
                    TableReader sub( r.buffer + r.offset, (int64_t) body_len, r.report, r.ids );
                    SessionInfoLoadBodyRetain( sub, nodes, value.info, retain, TableRetainStepInto( path, 1, (uint32_t) ( 0 ) ) );
                    if ( nodes.refused ) { return false; }
                    if ( sub.offset != sub.size )
                    {
                        r.report->damaged = true;
                        SessionInfoReset( value.info );
                    }
                }
                r.offset += (int64_t) body_len;
                break;
            }
            case 0xe4285b4aabc7d56bull: // transcript
            {
                if ( kind != 14 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                uint64_t body_len = 0;
                if ( !r.getleb( body_len ) || !r.room( body_len ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                int64_t body_end = r.offset + (int64_t) body_len;
                // A BODY TOO SHORT FOR ITS OWN HEADER is INERT (§4): the field keeps
                // the value it has, no counter is raised, and the walk continues past L.
                if ( body_len >= 2 )
                {
                    uint8_t elem_kind = r.get8();
                    uint64_t count = 0;
                    const bool counted_ok = r.getleb( count );
                    if ( !counted_ok ) { r.report->damaged = true; }
                    // AN ELEMENT KIND THAT DISAGREES with the reader's declaration is §3's
                    // element-kind rule: the field reads EMPTY and one kind_mismatch counts
                    else if ( elem_kind != 13 )
                    {
                        r.report->refused = true;
                        r.report->refuse_reason = kind_mismatch;
                        r.offset = body_end;
                        break;
                    }
                    else
                    {
                        // THE COUNT IS THE DATA'S (§2.9): there is no bound, so out_of_range
                        // cannot fire on it. A count above the int32 storage cap is the
                        // fill's refusal, and it moves no counter, the widening included.
                        // THE READ COMMITS TO REPLACE HERE (docs/SPEC-TABLES.md §6.6): the
                        // records under this field go with the value it is about to lose.
                        TableRetainDiscardField( retain, path, 2 );
                        TableListFill<StoreEntry> fill = TableListFillBegin( nodes, value.transcript, count );
                        if ( fill.refused )
                        {
                            nodes.refused = true;
                            return false;
                        }
                        if ( !fill.ok )
                        {
                            r.report->damaged = true;
                            r.offset = body_end;
                            break;
                        }
                        // elements are BOUNDED by the field body: a count the length cannot
                        // cover is damage, flags malformed, and the load is discarded
                        // whole (§4)
                        TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report, r.ids );
                        bool elements_consumed = true;
                        for ( uint64_t i = 0; i < count; i++ )
                        {
                            StoreEntry * slot = TableListFillNext( fill );
                            if ( slot == NULL )
                            {
                                if ( fill.worker != NULL )
                                {
                                    nodes.refused = true;
                                    return false;
                                }
                                r.report->damaged = true;
                                elements_consumed = false;
                                break;
                            } // the arena could not carve
                            bool landed = false;
                            do
                            {
                                uint64_t elem_len_transcript = 0;
                                if ( !sub.getleb( elem_len_transcript ) || !sub.room( elem_len_transcript ) )
                                {
                                    r.report->damaged = true;
                                    break;
                                }
                                {
                                    TableReader elem_transcript( sub.buffer + sub.offset, (int64_t) elem_len_transcript, r.report, r.ids );
                                    StoreEntryLoadBodyRetain( elem_transcript, nodes, ( *slot ), retain, TableRetainStepInto( path, 2, (uint32_t) ( i ) ) );
                                    if ( nodes.refused ) { return false; }
                                    if ( elem_transcript.offset != elem_transcript.size )
                                    {
                                        r.report->damaged = true;
                                        StoreEntryReset( ( *slot ) );
                                    }
                                }
                                sub.offset += (int64_t) elem_len_transcript;
                                landed = true;
                            } while ( 0 );
                            if ( !landed )
                            {
                                TableListFillDrop( fill );
                                elements_consumed = false;
                                break;
                            } // the element's own framing gave out before it decoded
                        }
                        TableListFillEnd( fill );
                        // EVERY BYTE OF THE L IS AN ELEMENT'S (§2.9, §4): bytes left
                        // inside the array frame after the count's elements are damage.
                        // A narrower element kind that does not fill the frame the writer
                        // sized is this case, and damage discards the load.
                        if ( elements_consumed && sub.offset != sub.size ) { r.report->damaged = true; }
                    }
                }
                r.offset = body_end; // the cursor closes the L (§4)
                break;
            }
            case 0xb11e8b146c5a21d8ull: // queue
            {
                if ( kind != 14 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                uint64_t body_len = 0;
                if ( !r.getleb( body_len ) || !r.room( body_len ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                int64_t body_end = r.offset + (int64_t) body_len;
                // A BODY TOO SHORT FOR ITS OWN HEADER is INERT (§4): the field keeps
                // the value it has, no counter is raised, and the walk continues past L.
                if ( body_len >= 2 )
                {
                    uint8_t elem_kind = r.get8();
                    uint64_t count = 0;
                    const bool counted_ok = r.getleb( count );
                    if ( !counted_ok ) { r.report->damaged = true; }
                    // AN ELEMENT KIND THAT DISAGREES with the reader's declaration is §3's
                    // element-kind rule: the field reads EMPTY and one kind_mismatch counts
                    else if ( elem_kind != 12 )
                    {
                        r.report->refused = true;
                        r.report->refuse_reason = kind_mismatch;
                        r.offset = body_end;
                        break;
                    }
                    else
                    {
                        // THE COUNT IS THE DATA'S (§2.9): there is no bound, so out_of_range
                        // cannot fire on it. A count above the int32 storage cap is the
                        // fill's refusal, and it moves no counter, the widening included.
                        TableListFill<StoreSessionQueueText> fill = TableListFillBegin( nodes, value.queue, count );
                        if ( fill.refused )
                        {
                            nodes.refused = true;
                            return false;
                        }
                        if ( !fill.ok )
                        {
                            r.report->damaged = true;
                            r.offset = body_end;
                            break;
                        }
                        // elements are BOUNDED by the field body: a count the length cannot
                        // cover is damage, flags malformed, and the load is discarded
                        // whole (§4)
                        TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report, r.ids );
                        bool elements_consumed = true;
                        for ( uint64_t i = 0; i < count; i++ )
                        {
                            StoreSessionQueueText * slot = TableListFillNext( fill );
                            if ( slot == NULL )
                            {
                                if ( fill.worker != NULL )
                                {
                                    nodes.refused = true;
                                    return false;
                                }
                                r.report->damaged = true;
                                elements_consumed = false;
                                break;
                            } // the arena could not carve
                            bool landed = false;
                            do
                            {
                                uint64_t elem_len_queue = 0;
                                if ( !sub.getleb( elem_len_queue ) || !sub.room( elem_len_queue ) )
                                {
                                    r.report->damaged = true;
                                    break;
                                }
                                if ( !TableUtf8Valid( sub.buffer + sub.offset, elem_len_queue ) )
                                {
                                    r.report->damaged = true;
                                    StoreSessionQueueTextReset( ( *slot ) );
                                    sub.offset += (int64_t) elem_len_queue;
                                    break;
                                }
                                if ( !schema_table_text_place_( nodes, ( ( *slot ) ).value, sub.buffer + sub.offset, (int64_t) elem_len_queue ) )
                                {
                                    if ( !nodes.refused ) { r.report->damaged = true; }
                                    break;
                                }
                                sub.offset += (int64_t) elem_len_queue;
                                landed = true;
                            } while ( 0 );
                            if ( !landed )
                            {
                                TableListFillDrop( fill );
                                elements_consumed = false;
                                break;
                            } // the element's own framing gave out before it decoded
                        }
                        TableListFillEnd( fill );
                        // EVERY BYTE OF THE L IS AN ELEMENT'S (§2.9, §4): bytes left
                        // inside the array frame after the count's elements are damage.
                        // A narrower element kind that does not fill the frame the writer
                        // sized is this case, and damage discards the load.
                        if ( elements_consumed && sub.offset != sub.size ) { r.report->damaged = true; }
                        if ( nodes.refused ) { return false; }
                    }
                }
                r.offset = body_end; // the cursor closes the L (§4)
                break;
            }
            case 0xc85b78e3dea334ffull: // driver
            {
                if ( kind != 13 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                TableRetainDiscardField( retain, path, 4 );
                uint64_t body_len = 0;
                if ( !r.getleb( body_len ) || !r.room( body_len ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                {
                    TableReader sub( r.buffer + r.offset, (int64_t) body_len, r.report, r.ids );
                    DriverLoadBodyRetain( sub, nodes, value.driver, retain, TableRetainStepInto( path, 4, (uint32_t) ( 0 ) ) );
                    if ( nodes.refused ) { return false; }
                    if ( sub.offset != sub.size )
                    {
                        r.report->damaged = true;
                        DriverReset( value.driver );
                    }
                }
                r.offset += (int64_t) body_len;
                break;
            }
            case 0xffffffffffffffffull:
            {
                if ( !r.skip( kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !TableRetainCapture( retain, r, path, field_id, kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
        }
    }
}

template <typename Ctx>
inline int64_t ClientCounterMeasureBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableRetainIds & ids, const ClientCounter & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    int64_t bytes = 1; // the ZERO REFERENCE that ends the body
    {
        const TableBlob * blob_client = TableBlobAt( ctx, value.client ); // *string
        // A BYTE BUFFER RIDES AS A NODE INDEX too (docs/SPEC-TABLES.md §2.5,
        // §3.1): the header and the index here, the bytes themselves as a
        // record in the node table. Null is elided and a non-null blob always
        // rides, even at length zero — null and empty are two values.
        if ( blob_client != NULL )
        {
            uint64_t index_client = 0;
            if ( !TableNumberingIndex( numbering, (const void *) blob_client, index_client ) ) { return -1; }
            bytes += TableLebBytes( ids.ref_at( 61, 0xc47ea73e7986f3deull ) ) + 1 + TableLebBytes( index_client );
        }
    }
    if ( value.applied != 0 ) { bytes += TableLebBytes( ids.ref_at( 44, 0x8bf75481a1d237caull ) ) + 1 + 8; } // applied
    bytes += TableRetainTailMeasure( retain, ids, path );
    return bytes;
}

template <typename Ctx>
inline bool ClientCounterSaveBodyFieldsRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const ClientCounter & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    {
        const TableBlob * blob_client = TableBlobAt( ctx, value.client ); // *string
        if ( blob_client != NULL )
        {
            uint64_t index_client = 0;
            if ( !TableNumberingIndex( numbering, (const void *) blob_client, index_client ) ) { return false; }
            w.header( ids.ref_at( 61, 0xc47ea73e7986f3deull ), 17 ); // client — a NODE INDEX into the flat node table
            w.putleb( index_client );
        }
    }
    if ( value.applied != 0 )
    {
        w.header( ids.ref_at( 44, 0x8bf75481a1d237caull ), 9 ); // applied
        w.put64( uint64_t( value.applied ) );
    }
    if ( !TableRetainTailSave( retain, ids, w, path ) ) { return false; }
    return !w.overflow;
}

template <typename Ctx>
inline bool ClientCounterSaveBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const ClientCounter & value, TableRetain * retain, const TableRetainPath & path )
{
    if ( !ClientCounterSaveBodyFieldsRetain( ctx, numbering, w, ids, value, retain, path ) ) { return false; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the body
    return !w.overflow;
}

inline bool ClientCounterLoadBodyRetain( TableReader & r, const TableNodeMap & nodes, ClientCounter & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) nodes;
    if ( nodes.refused ) { return false; }
    ClientCounterReset( value ); // prefill declared defaults in place, then overlay
    // A RETAINED RECORD DIES WITH THE BODY OCCURRENCE THAT CARRIED IT
    // (docs/SPEC-TABLES.md §6.6): this body is being established, so
    // whatever an earlier occurrence of it left is discarded before the
    // winning one is read. The discard moves neither counter.
    TableRetainDiscardBody( retain, path );
    for ( ;; )
    {
        uint64_t field_ref = 0;
        if ( !r.getleb( field_ref ) )
        {
            r.report->damaged = true;
            return false;
        }
        if ( field_ref == 0 )
        {
            return true;
        }
        if ( r.ids == NULL || field_ref > (uint64_t) r.ids->count )
        {
            r.report->damaged = true;
            return false;
        } // a reference ABOVE the entry count
        const uint64_t field_id = r.ids->at( field_ref );
        if ( !r.has( 1 ) )
        {
            r.report->damaged = true;
            return false;
        }
        uint8_t kind = r.get8();
        if ( ( field_id == kTableNodeTableFieldId && r.nested ) || field_id == kTableBuildVersionFieldId || field_id == kTableMessageVocabularyFieldId )
        {
            // A RESERVED ID IN ANY BODY BUT THE ONE WHOSE TRANSPORT IT IS,
            // IS MALFORMED (docs/SPEC-TABLES.md §3.1, §3.3). The node
            // table's is the ROOT body's alone, on the numbering's own
            // rule — a second numbering cannot exist — and the BUILD
            // VERSION's rides in the announcement and nowhere else. That
            // is damage, and damage discards the whole load (§4).
            r.report->damaged = true;
            return false;
        }
        switch ( field_id )
        {
            case 0xc47ea73e7986f3deull: // client
            {
                if ( kind != 17 )
                {
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                // A POINTER FIELD'S PAYLOAD IS A NUMBER (docs/SPEC-TABLES.md §3.1): it is
                // bounds-checked and resolved through the numbering, never FOLLOWED, so
                // there is no traversal here and therefore no traversal bound.
                {
                    uint64_t node_index = 0;
                    if ( !r.getleb( node_index ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    TableNodeResolve( nodes, value.client, node_index, kTableStringTypeId, r.report ); // *string
                }
                break;
            }
            case 0x8bf75481a1d237caull: // applied
            {
                if ( kind != 9 )
                {
                    if ( TableKindWidens( kind, 9 ) )
                    {
                        // WIDENED (§4): a kind that grew since the writer decodes
                        // exactly at its own width, the value lands, one widened counts
                        uint64_t widened_v = 0;
                        if ( !TableReadUnsignedAt( r, kind, widened_v ) )
                        {
                            r.report->damaged = true;
                            return false;
                        }
                        uint64_t decoded_v = (uint64_t) widened_v;
                        value.applied = decoded_v;
                        r.report->widened++;
                        break;
                    }
                    // AT A POSITION THE READER DOES NAME, a field under
                    // kind 31 or kind 32 takes this same rule and no other (§3)
                    r.report->refused = true;
                    r.report->refuse_reason = kind_mismatch;
                    if ( !r.skip( kind ) )
                    {
                        r.report->damaged = true;
                        return false;
                    }
                    break;
                }
                if ( !r.has( 8 ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                uint64_t decoded_v = uint64_t( r.get64() );
                value.applied = decoded_v;
                break;
            }
            case 0xffffffffffffffffull:
            {
                if ( !r.skip( kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !TableRetainCapture( retain, r, path, field_id, kind ) )
                {
                    r.report->damaged = true;
                    return false;
                }
                break;
            }
        }
    }
}

template <typename Ctx>
inline int64_t SnapshotMeasureBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableRetainIds & ids, const Snapshot & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    int64_t bytes = 1; // the ZERO REFERENCE that ends the body
    if ( value.next_session != 0 ) { bytes += TableLebBytes( ids.ref_at( 8, 0x17b96c48ba4cbde7ull ) ) + 1 + 8; } // next_session
    {
        // sessions: a kind 14 array of kind 13 elements, INDEX order (§2.9)
        TableListCursor<StoreSession> cursor_sessions = TableListElements( ctx, value.sessions );
        if ( !cursor_sessions.ok ) { return -1; } // the slot and the head disagree
        if ( cursor_sessions.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_sessions = ids.ref_at( 56, 0xacebadbd2040ebacull );
            int64_t body_sessions = 0;
            body_sessions += 1 + TableLebBytes( (uint64_t) ( cursor_sessions.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                const int64_t elem_bytes_sessions = StoreSessionMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 1, (uint32_t) ( elem_i_sessions ) ) );
                if ( elem_bytes_sessions < 0 ) { return -1; }
                body_sessions += TableLebBytes( (uint64_t) ( elem_bytes_sessions ) ) + ( elem_bytes_sessions );
            }
            bytes += TableLebBytes( ref_sessions ) + 1 + TableLebBytes( (uint64_t) ( body_sessions ) ) + ( body_sessions );
        }
    }
    {
        // clients: a kind 14 array of kind 13 elements, INDEX order (§2.9)
        TableListCursor<ClientCounter> cursor_clients = TableListElements( ctx, value.clients );
        if ( !cursor_clients.ok ) { return -1; } // the slot and the head disagree
        if ( cursor_clients.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_clients = ids.ref_at( 33, 0x6a29dc2880500ef7ull );
            int64_t body_clients = 0;
            body_clients += 1 + TableLebBytes( (uint64_t) ( cursor_clients.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_clients = 0; elem_i_clients < cursor_clients.count; elem_i_clients++ )
            {
                const int64_t elem_bytes_clients = ClientCounterMeasureBodyRetain( ctx, numbering, ids, cursor_clients[elem_i_clients], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_clients ) ) );
                if ( elem_bytes_clients < 0 ) { return -1; }
                body_clients += TableLebBytes( (uint64_t) ( elem_bytes_clients ) ) + ( elem_bytes_clients );
            }
            bytes += TableLebBytes( ref_clients ) + 1 + TableLebBytes( (uint64_t) ( body_clients ) ) + ( body_clients );
        }
    }
    bytes += TableRetainTailMeasure( retain, ids, path );
    return bytes;
}

template <typename Ctx>
inline bool SnapshotSaveBodyFieldsRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const Snapshot & value, TableRetain * retain, const TableRetainPath & path )
{
    (void) ctx;
    (void) numbering;
    if ( value.next_session != 0 )
    {
        w.header( ids.ref_at( 8, 0x17b96c48ba4cbde7ull ), 9 ); // next_session
        w.put64( uint64_t( value.next_session ) );
    }
    {
        TableListCursor<StoreSession> cursor_sessions = TableListElements( ctx, value.sessions ); // sessions
        if ( !cursor_sessions.ok ) { return false; }
        if ( cursor_sessions.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_sessions = ids.ref_at( 56, 0xacebadbd2040ebacull );
            int64_t body_sessions = 0;
            body_sessions += 1 + TableLebBytes( (uint64_t) ( cursor_sessions.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                const int64_t elem_bytes_sessions = StoreSessionMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 1, (uint32_t) ( elem_i_sessions ) ) );
                if ( elem_bytes_sessions < 0 ) { return false; }
                body_sessions += TableLebBytes( (uint64_t) ( elem_bytes_sessions ) ) + ( elem_bytes_sessions );
            }
            w.header( ref_sessions, 14 );
            w.putleb( (uint64_t) body_sessions ); // sessions
            w.put8( 13 );
            w.putleb( (uint64_t) ( cursor_sessions.count ) );
            for ( int32_t elem_i_sessions = 0; elem_i_sessions < cursor_sessions.count; elem_i_sessions++ )
            {
                {
                    const int64_t elem_len_sessions = StoreSessionMeasureBodyRetain( ctx, numbering, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 1, (uint32_t) ( elem_i_sessions ) ) );
                    if ( elem_len_sessions < 0 ) return false;
                    w.putleb( (uint64_t) elem_len_sessions );
                    if ( !StoreSessionSaveBodyRetain( ctx, numbering, w, ids, cursor_sessions[elem_i_sessions], retain, TableRetainStepInto( path, 1, (uint32_t) ( elem_i_sessions ) ) ) ) return false;
                }
            }
        }
    }
    {
        TableListCursor<ClientCounter> cursor_clients = TableListElements( ctx, value.clients ); // clients
        if ( !cursor_clients.ok ) { return false; }
        if ( cursor_clients.count > 0 ) // an EMPTY list elides, the by-value rule (§3)
        {
            const uint64_t ref_clients = ids.ref_at( 33, 0x6a29dc2880500ef7ull );
            int64_t body_clients = 0;
            body_clients += 1 + TableLebBytes( (uint64_t) ( cursor_clients.count ) ); // the element kind byte and the count
            for ( int32_t elem_i_clients = 0; elem_i_clients < cursor_clients.count; elem_i_clients++ )
            {
                const int64_t elem_bytes_clients = ClientCounterMeasureBodyRetain( ctx, numbering, ids, cursor_clients[elem_i_clients], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_clients ) ) );
                if ( elem_bytes_clients < 0 ) { return false; }
                body_clients += TableLebBytes( (uint64_t) ( elem_bytes_clients ) ) + ( elem_bytes_clients );
            }
            w.header( ref_clients, 14 );
            w.putleb( (uint64_t) body_clients ); // clients
            w.put8( 13 );
            w.putleb( (uint64_t) ( cursor_clients.count ) );
            for ( int32_t elem_i_clients = 0; elem_i_clients < cursor_clients.count; elem_i_clients++ )
            {
                {
                    const int64_t elem_len_clients = ClientCounterMeasureBodyRetain( ctx, numbering, ids, cursor_clients[elem_i_clients], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_clients ) ) );
                    if ( elem_len_clients < 0 ) return false;
                    w.putleb( (uint64_t) elem_len_clients );
                    if ( !ClientCounterSaveBodyRetain( ctx, numbering, w, ids, cursor_clients[elem_i_clients], retain, TableRetainStepInto( path, 2, (uint32_t) ( elem_i_clients ) ) ) ) return false;
                }
            }
        }
    }
    if ( !TableRetainTailSave( retain, ids, w, path ) ) { return false; }
    return !w.overflow;
}

template <typename Ctx>
inline bool SnapshotSaveBodyRetain( const Ctx & ctx, const TableNumbering & numbering, TableWriter & w, TableRetainIds & ids, const Snapshot & value, TableRetain * retain, const TableRetainPath & path )
{
    if ( !SnapshotSaveBodyFieldsRetain( ctx, numbering, w, ids, value, retain, path ) ) { return false; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the body
    return !w.overflow;
}

