    table_cook_put( at + 88, (uint64_t) value.keep_from, 8, order );
    table_cook_put( at + 96, 0, 8, order ); // entries: the array's delta, filled by the extent writer
    table_cook_put( at + 104, 0, 4, order ); // and its count
