// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx>
inline bool StoreSessionQueueTextCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const StoreSessionQueueText & value, TableByteOrder order )
{
    (void) region; // a table element's and an entry's references resolve through their own bodies
    { // value: an unbounded text's bytes
        int32_t len = 0;
        const char * bytes = schema_table_text_at_( ctx, value.value, len );
        if ( bytes == NULL ) { return false; }
        if ( len == 0 )
        {
            table_cook_put( record + 0, 0, 8, order );
        }
        else
        {
            at = ( at + 7 ) & ~(int64_t) 7;
            uint8_t * block = extent + at;
            at += TableAlignUp64( 9 + (int64_t) len );
            table_cook_put( record + 0, (uint64_t) (int64_t) ( block - ( record + 0 ) ), 8, order );
            table_cook_put( block, (uint64_t) (uint32_t) len, 4, order );
            table_cook_put( block + 4, 0, 4, order );
            memcpy( block + 8, bytes, (size_t) len );
            block[8 + len] = 0;
        }
    }
    return true;
}

// StoreSessionCookExtent: StoreSession's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx>
inline bool StoreSessionCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const StoreSession & value, TableByteOrder order )
{
    (void) region; // a table element's and an entry's references resolve through their own bodies
    { // transcript: an unbounded array
        TableListCursor<StoreEntry> cursor = TableListElements( ctx, value.transcript );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( StoreEntry )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 16; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 64, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 64 ) ) : 0, 8, order );
        table_cook_put( record + 72, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            if ( !StoreEntryCookBody( ctx, region, array + i * 16, cursor[i], order ) ) { return false; }
        }
    }
    { // queue: an unbounded array
        TableListCursor<StoreSessionQueueText> cursor = TableListElements( ctx, value.queue );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( StoreSessionQueueText )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 8; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 80, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 80 ) ) : 0, 8, order );
        table_cook_put( record + 88, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            if ( !StoreSessionQueueTextCookBody( ctx, region, array + i * 8, cursor[i], order ) ) { return false; }
        }
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, element by element in index order
        {
            if ( !StoreSessionQueueTextCookExtent( ctx, region, extent, at, array + i * 8, cursor[i], order ) ) { return false; }
        }
    }
    { // driver (nested by value)
        if ( !DriverCookExtent( ctx, region, extent, at, record + 96, value.driver, order ) ) { return false; }
    }
    return true;
}

// ClientCounterCookExtent: ClientCounter's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx>
inline bool ClientCounterCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const ClientCounter & value, TableByteOrder order )
{
    (void) ctx;
    (void) region;
    (void) extent;
    (void) at;
    (void) record;
    (void) value;
    (void) order;
    return true; // no list or map below this record
}

// SnapshotCookExtent: Snapshot's arrays into the node's extent, PRE-ORDER, a map's entries
// in ASCENDING key order and a list's elements in INDEX order, each through its
// own cook writer (§2.8, §2.9, §7.6).
template <typename Ctx>
inline bool SnapshotCookExtent( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Snapshot & value, TableByteOrder order )
{
    (void) region; // a table element's and an entry's references resolve through their own bodies
    { // sessions: an unbounded array
        TableListCursor<StoreSession> cursor = TableListElements( ctx, value.sessions );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( StoreSession )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 152; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 8, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 8 ) ) : 0, 8, order );
        table_cook_put( record + 16, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            if ( !StoreSessionCookBody( ctx, region, array + i * 152, cursor[i], order ) ) { return false; }
        }
        for ( int32_t i = 0; i < cursor.count; i++ ) // then, element by element in index order
        {
            if ( !StoreSessionCookExtent( ctx, region, extent, at, array + i * 152, cursor[i], order ) ) { return false; }
        }
    }
    { // clients: an unbounded array
        TableListCursor<ClientCounter> cursor = TableListElements( ctx, value.clients );
        if ( !cursor.ok ) { return false; }
        at = ( at + 7 ) & ~(int64_t) 7; // at alignof( ClientCounter )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 16; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 24, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 24 ) ) : 0, 8, order );
        table_cook_put( record + 32, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ ) // INDEX order, live elements only
        {
            if ( !ClientCounterCookBody( ctx, region, array + i * 16, cursor[i], order ) ) { return false; }
        }
    }
    return true;
}

